import{AuthKey,InitiatorAuthKey,ParentSessionKey,SessionIdKey,SessionKey,SessionPredecessorKey}from"#context/keys.js";import{activeTurnId,turnPosition}from"#harness/session-machine/view.js";import{projectionFor}from"#harness/session-machine/current.js";const sessionProvider={key:SessionKey,create(e,t){let n=e.require(AuthKey),r=turnPosition(projectionFor(e,t.state)),i=activeTurnId(r);return{value:Object.freeze({auth:{current:n,initiator:e.get(InitiatorAuthKey)??n},parent:e.get(ParentSessionKey),predecessor:e.get(SessionPredecessorKey),sessionId:e.require(SessionIdKey),turn:{id:i,sequence:r.sequence}})}}};export{sessionProvider};